import { useState } from "react";
import "../../css/layout.css";
import "../../css/theme.css";
import "../../css/components.css";
import AdminLayout from "../AdminLayout.jsx";
import "./Dashboard.css";
import { mockDashboard } from "./mockDashboard.js";

// Admin dashboard, shown at /admin/dashboard. Layout follows the Figma "Admin / Dashboard" frame.
// Sprint 1: uses mock data from mockDashboard.js.
// These are mock data only, claude will be holding this page until we have the proper data tables to fill it in.

const money = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
});

function toDate(isoDate) {
    return new Date(`${isoDate}T00:00:00`);
}

// "Oct 20 • 6 PM"
function formatShort(item) {
    const day = toDate(item.date).toLocaleDateString("en-US", { month: "short", day: "numeric" });
    return `${day} • ${item.startTime.replace(":00", "")}`;
}

// "Tuesday, October 20 • 6:00–7:00 PM"
function formatLong(item) {
    const day = toDate(item.date).toLocaleDateString("en-US", {
        weekday: "long",
        month: "long",
        day: "numeric",
    });
    const start = item.startTime.slice(-2) === item.endTime.slice(-2)
        ? item.startTime.slice(0, -3)
        : item.startTime;
    return `${day} • ${start}–${item.endTime}`;
}

function Dashboard() {
    const { stats, upcomingClasses } = mockDashboard;
    const [selectedId, setSelectedId] = useState(null);
    const selected = upcomingClasses.find((item) => item.id === selectedId);

    const cards = [
        { label: "Upcoming classes", value: stats.upcomingClasses, href: "/admin/classes" },
        { label: "Pending volunteers", value: stats.pendingVolunteers, href: "/admin/volunteers" },
        { label: "Recent donations", value: money.format(stats.recentDonations), href: "/admin/donations" },
        { label: "Registered attendees", value: stats.registeredAttendees, href: "/admin/viewusers" },
    ];

    return (
        <AdminLayout>
            <h1>Dashboard</h1>
            <p className="admin-subtitle">A quick overview of Heal One World's website activity.</p>

            <section className="admin-dashboard__stats" aria-label="Summary">
                {cards.map((card) => (
                    <a key={card.label} className="admin-dashboard__stat" href={card.href}>
                        <span className="admin-dashboard__stat-label">{card.label}</span>
                        <span className="admin-dashboard__stat-value">{card.value}</span>
                    </a>
                ))}
            </section>

            <section aria-labelledby="upcoming-heading">
                <h2 id="upcoming-heading">Upcoming activity</h2>
                {upcomingClasses.length === 0 ? (
                    <p>No upcoming classes or events.</p>
                ) : (
                    <ul className="admin-dashboard__list">
                        {upcomingClasses.map((item) => (
                            <li key={item.id}>
                                <button
                                    type="button"
                                    className="admin-row admin-dashboard__row"
                                    aria-expanded={item.id === selectedId}
                                    aria-controls="activity-detail"
                                    onClick={() => setSelectedId(item.id === selectedId ? null : item.id)}
                                >
                                    <span>{item.name}</span>
                                    <span>{formatShort(item)}</span>
                                    <span>{item.registered} registered</span>
                                </button>
                            </li>
                        ))}
                    </ul>
                )}

                {selected && (
                    <div id="activity-detail" className="admin-dashboard__detail" role="region" aria-label={`${selected.name} details`}>
                        <button
                            type="button"
                            className="admin-dashboard__close"
                            aria-label="Close details"
                            onClick={() => setSelectedId(null)}
                        >
                            ×
                        </button>
                        <h3>{selected.name}</h3>
                        <p>{formatLong(selected)}</p>
                        <p>{selected.format} • {selected.location}</p>
                        <p className="admin-dashboard__detail-gap">
                            {selected.registered} registered • Capacity {selected.capacity}
                        </p>
                        <p>Instructor: {selected.instructor}</p>
                        <p className="admin-dashboard__detail-label">Quick actions</p>
                        <div className="admin-dashboard__actions">
                            <a className="admin-dashboard__action" href={`/admin/classes/${selected.id}`}>
                                View class
                            </a>
                            <a
                                className="admin-dashboard__action admin-dashboard__action--secondary"
                                href={`/admin/classes/${selected.id}/edit`}
                            >
                                Edit
                            </a>
                        </div>
                    </div>
                )}
            </section>
        </AdminLayout>
    );
}

export default Dashboard;
